CREATE OR REPLACE FUNCTION public.lead_aanvraag_voorinvullen(_bron_tabel text,_bron_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r jsonb; BEGIN PERFORM public.a19_team(); IF _bron_tabel='leads' THEN SELECT to_jsonb(l) INTO r FROM public.leads l WHERE id=_bron_id; ELSIF _bron_tabel='aanvraag_concepten' THEN SELECT to_jsonb(c) INTO r FROM public.aanvraag_concepten c WHERE id=_bron_id AND geanonimiseerd_op IS NULL; ELSE RAISE EXCEPTION 'Onbekende leadbron'; END IF; IF r IS NULL THEN RAISE EXCEPTION 'Lead niet gevonden'; END IF; IF coalesce((r->>'is_test')::boolean,false) AND NOT public.is_supervisor_or_admin(auth.uid()) THEN RAISE EXCEPTION 'Geen toegang tot testrecords'; END IF; RETURN jsonb_build_object('voornaam',r->>'voornaam','achternaam',r->>'achternaam','bedrijfsnaam',r->>'bedrijfsnaam','email',r->>'email','telefoon',r->>'telefoon','kvkNummer',coalesce(r->>'kvk_nummer',r->>'kvk'),'beroep',r->>'beroep'); END $$;
REVOKE ALL ON FUNCTION public.lead_aanvraag_voorinvullen(text,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.lead_aanvraag_voorinvullen(text,uuid) TO authenticated;